Write a JavaScript function that checks whether a passed string is a valid IP address.

To validate an IPv4 address in JavaScript, you need to ensure the string consists of exactly four octets, each being a number between 0 and 255, with no leading zeros (unless the number is exactly 0) and no non-numeric characters.

Here is a robust implementation using a regular expression:

```javascript
function isValidIP(ip) {
    // Regular expression to match IPv4 addresses
    // Each octet: 0-255
    // (25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)
    const ipv4Pattern = /^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;

    if (!ipv4Pattern.test(ip)) {
        return false;
    }

    // Additional check to prevent leading zeros (e.g., "192.168.01.1")
    const segments = ip.split('.');
    return segments.every(segment => {
        if (segment.length > 1 && segment.startsWith('0')) {
            return false;
        }
        return true;
    });
}

// Test cases
console.log(isValidIP("192.168.1.1"));   // true
console.log(isValidIP("255.255.255.255")); // true
console.log(isValidIP("0.0.0.0"));       // true
console.log(isValidIP("256.1.1.1"));     // false (out of range)
console.log(isValidIP("192.168.1"));     // false (too few segments)
console.log(isValidIP("192.168.1.1.1")); // false (too many segments)
console.log(isValidIP("192.168.1.abc")); // false (non-numeric)
console.log(isValidIP("192.168.01.1"));  // false (leading zero)
```

